"""Durable state for relay, backed by sqlite.

Convention: this module is the only place that opens sqlite. Everything
durable goes through a connection from `connect()`, and multi-statement
writes go through `Store.tx()`.
"""
from __future__ import annotations

import contextlib
import sqlite3
import time
from typing import Iterator

from . import faults
from .model import Job

SCHEMA = """
CREATE TABLE IF NOT EXISTS jobs (
    job_id TEXT PRIMARY KEY,
    state  TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS events (
    seq        INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id   TEXT NOT NULL UNIQUE,
    job_id     TEXT NOT NULL,
    command_id TEXT NOT NULL,
    type       TEXT NOT NULL,
    state      TEXT NOT NULL,
    created_at REAL NOT NULL
);
"""


def connect(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path, isolation_level=None, check_same_thread=False)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=FULL")
    return faults.wrap(conn)


class Store:
    def __init__(self, path: str):
        self.path = path
        self.conn = connect(path)
        for stmt in SCHEMA.strip().split(";"):
            if stmt.strip():
                self.conn.execute(stmt)

    @contextlib.contextmanager
    def tx(self) -> Iterator[None]:
        """Run the block atomically. Nested use is not supported."""
        self.conn.execute("BEGIN IMMEDIATE")
        try:
            yield
        except BaseException:
            self.conn.execute("ROLLBACK")
            raise
        else:
            self.conn.execute("COMMIT")

    # -- jobs ---------------------------------------------------------------
    def get_job(self, job_id: str) -> Job | None:
        row = self.conn.execute("SELECT job_id, state FROM jobs WHERE job_id = ?", (job_id,)).fetchone()
        return Job(*row) if row else None

    def set_job_state(self, job_id: str, state: str) -> None:
        self.conn.execute(
            "INSERT INTO jobs (job_id, state) VALUES (?, ?) "
            "ON CONFLICT(job_id) DO UPDATE SET state = excluded.state",
            (job_id, state),
        )

    # -- events -------------------------------------------------------------
    def append_event(self, event_id: str, job_id: str, command_id: str, type_: str, state: str) -> None:
        self.conn.execute(
            "INSERT INTO events (event_id, job_id, command_id, type, state, created_at) VALUES (?, ?, ?, ?, ?, ?)",
            (event_id, job_id, command_id, type_, state, time.time()),
        )

    def read_events(self, job_id: str | None = None) -> list[dict]:
        if job_id is None:
            rows = self.conn.execute("SELECT seq, event_id, job_id, command_id, type, state FROM events ORDER BY seq").fetchall()
        else:
            rows = self.conn.execute(
                "SELECT seq, event_id, job_id, command_id, type, state FROM events WHERE job_id = ? ORDER BY seq",
                (job_id,),
            ).fetchall()
        keys = ("seq", "event_id", "job_id", "command_id", "type", "state")
        return [dict(zip(keys, r)) for r in rows]

    def close(self) -> None:
        self.conn.close()

"""Apply commands to jobs, log the resulting events, notify the sink.

A command is a dict:
    {"command_id": str, "type": str, "job_id": str, "payload": dict}

`handle` returns {"ok": True, "state": ..., "event_id": ...} on success or
{"ok": False, "error": CODE} on rejection.
"""
from __future__ import annotations

import uuid

from .model import err, ok
from .notifier import Notifier
from .store import Store


class Dispatcher:
    def __init__(self, store: Store, notifier: Notifier):
        self.store = store
        self.notifier = notifier

    def handle(self, command: dict) -> dict:
        ctype = command["type"]
        job_id = command["job_id"]
        command_id = command["command_id"]

        job = self.store.get_job(job_id)
        if ctype == "create":
            if job is not None:
                return err("JOB_EXISTS")
            new_state = "queued"
        else:
            if job is None:
                return err("JOB_NOT_FOUND")
            if ctype == "start":
                # (Re)start is always allowed; operators use it to kick a stuck job.
                new_state = "running"
            elif ctype == "complete":
                if job.state != "running":
                    return err("INVALID_TRANSITION")
                new_state = "succeeded"
            elif ctype == "fail":
                if job.state != "running":
                    return err("INVALID_TRANSITION")
                new_state = "failed"
            else:
                return err("UNKNOWN_COMMAND")

        event_id = str(uuid.uuid4())
        self.store.set_job_state(job_id, new_state)
        self.store.append_event(event_id, job_id, command_id, ctype, new_state)
        self.notifier.send(
            {"event_id": event_id, "job_id": job_id, "type": ctype, "state": new_state}
        )
        return ok(new_state, event_id)

    def pump(self) -> int:
        """Do any pending background work. Returns the number of items processed.

        Called periodically by the host process (a scheduler in production,
        the test harness in tests).
        """
        return 0

"""Job state machine.

    queued --start--> running --complete--> succeeded
                              --fail-----> failed

`succeeded`, `failed` and `cancelled` are terminal.
"""
from __future__ import annotations

from dataclasses import dataclass

STATES = ("queued", "running", "succeeded", "failed", "cancelled")
TERMINAL = frozenset({"succeeded", "failed", "cancelled"})


@dataclass(frozen=True)
class Job:
    job_id: str
    state: str

    @property
    def terminal(self) -> bool:
        return self.state in TERMINAL


def ok(state: str, event_id: str) -> dict:
    return {"ok": True, "state": state, "event_id": event_id}


def err(code: str) -> dict:
    return {"ok": False, "error": code}

"""Fault injection for the sqlite connection.

Production never sets RELAY_FAULT. Tests and the operations harness set it to
make the process die at a precise point in its write sequence, so that
crash/restart behaviour is reproducible:

    RELAY_FAULT=commit:3   exit immediately after the 3rd commit completes
    RELAY_FAULT=write:3    exit immediately after the 3rd write statement
                           executes, before it is committed

Every durable write in relay goes through the connection returned by
`relay.store.connect`, which is what makes this counting exact. Keep it that
way: open sqlite only via `relay.store.connect`.
"""
from __future__ import annotations

import os
import sqlite3
import sys

_WRITE_VERBS = ("INSERT", "UPDATE", "DELETE", "REPLACE")


def _die(reason: str) -> None:
    sys.stderr.write(f"[relay.faults] simulated crash: {reason}\n")
    sys.stderr.flush()
    os._exit(137)


class FaultConnection:
    """Proxy around sqlite3.Connection that counts writes and commits."""

    def __init__(self, conn: sqlite3.Connection, spec: str):
        kind, _, n = spec.partition(":")
        if kind not in ("commit", "write") or not n.isdigit():
            raise ValueError(f"bad RELAY_FAULT spec: {spec!r}")
        self._conn = conn
        self._kind = kind
        self._target = int(n)
        self._writes = 0
        self._commits = 0

    # -- counting -----------------------------------------------------------
    def _saw_write(self) -> None:
        self._writes += 1
        if self._kind == "write" and self._writes == self._target:
            _die(f"after write #{self._writes}")

    def _saw_commit(self) -> None:
        self._commits += 1
        if self._kind == "commit" and self._commits == self._target:
            _die(f"after commit #{self._commits}")

    # -- sqlite3.Connection surface used by relay ---------------------------
    def execute(self, sql: str, params=()):
        verb = sql.lstrip().split(None, 1)[0].upper() if sql.strip() else ""
        was_in_tx = self._conn.in_transaction
        cur = self._conn.execute(sql, params)
        if verb in _WRITE_VERBS:
            self._saw_write()
            if not self._conn.in_transaction:
                # autocommit: the write is already durable
                self._saw_commit()
        elif verb == "COMMIT" or (verb == "END" and was_in_tx):
            self._saw_commit()
        return cur

    def commit(self) -> None:
        was_in_tx = self._conn.in_transaction
        self._conn.commit()
        if was_in_tx:
            self._saw_commit()

    def rollback(self) -> None:
        self._conn.rollback()

    def close(self) -> None:
        self._conn.close()

    @property
    def in_transaction(self) -> bool:
        return self._conn.in_transaction

    def __getattr__(self, name):
        return getattr(self._conn, name)


def wrap(conn: sqlite3.Connection) -> sqlite3.Connection | FaultConnection:
    spec = os.environ.get("RELAY_FAULT")
    if not spec:
        return conn
    return FaultConnection(conn, spec)

"""Announce state changes to an external sink over HTTP."""
from __future__ import annotations

import json
import urllib.error
import urllib.request


class NotifyError(Exception):
    pass


class Notifier:
    def __init__(self, sink_url: str, timeout: float = 2.0):
        self.sink_url = sink_url
        self.timeout = timeout

    def send(self, notification: dict) -> None:
        """POST one notification. Raises NotifyError on any failure."""
        body = json.dumps(notification).encode()
        req = urllib.request.Request(
            self.sink_url, data=body, method="POST", headers={"content-type": "application/json"}
        )
        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                if resp.status >= 300:
                    raise NotifyError(f"sink returned {resp.status}")
        except urllib.error.HTTPError as e:
            raise NotifyError(f"sink returned {e.code}") from e
        except (urllib.error.URLError, OSError) as e:
            raise NotifyError(f"sink unreachable: {e}") from e

