"""Apply commands to jobs, log the resulting events, notify the sink.

A command is a dict:
    {"command_id": str, "type": str, "job_id": str, "payload": dict}

`handle` returns {"ok": True, "state": ..., "event_id": ...} on success or
{"ok": False, "error": CODE} on rejection.
"""
from __future__ import annotations

import json
import uuid

from .model import err, ok
from .notifier import Notifier
from .store import Store


class Dispatcher:
    def __init__(self, store: Store, notifier: Notifier):
        self.store = store
        self.notifier = notifier

    def handle(self, command: dict) -> dict:
        ctype = command["type"]
        job_id = command["job_id"]
        command_id = command["command_id"]
        request_json = json.dumps(
            {"type": ctype, "job_id": job_id, "payload": command["payload"]},
            sort_keys=True,
            separators=(",", ":"),
        )

        recorded = self.store.get_command(command_id)
        if recorded is not None:
            return self._recorded_result(recorded, request_json)

        accepted = False
        with self.store.tx():
            # Another process may have committed this command while BEGIN
            # IMMEDIATE was waiting for the writer lock.
            recorded = self.store.get_command(command_id)
            if recorded is not None:
                return self._recorded_result(recorded, request_json)

            job = self.store.get_job(job_id)
            if job is not None and job.terminal:
                result = err("INVALID_TRANSITION")
            elif ctype == "create":
                if job is not None:
                    result = err("JOB_EXISTS")
                else:
                    result = self._accept(job_id, command_id, ctype, "queued")
                    accepted = True
            elif job is None:
                result = err("JOB_NOT_FOUND")
            elif ctype == "start":
                result = self._accept(job_id, command_id, ctype, "running")
                accepted = True
            elif ctype == "complete":
                if job.state != "running":
                    result = err("INVALID_TRANSITION")
                else:
                    result = self._accept(job_id, command_id, ctype, "succeeded")
                    accepted = True
            elif ctype == "fail":
                if job.state != "running":
                    result = err("INVALID_TRANSITION")
                else:
                    result = self._accept(job_id, command_id, ctype, "failed")
                    accepted = True
            elif ctype == "cancel":
                result = self._accept(job_id, command_id, ctype, "cancelled")
                accepted = True
            else:
                result = err("UNKNOWN_COMMAND")

            self.store.record_command(
                command_id,
                request_json,
                json.dumps(result, sort_keys=True, separators=(",", ":")),
            )

        if accepted:
            # Preserve the original low-latency behavior, but delivery is now
            # best-effort here and durable/retryable through pump().
            try:
                self.pump()
            except Exception:
                pass
        return result

    @staticmethod
    def _recorded_result(recorded: tuple[str, str], request_json: str) -> dict:
        recorded_request, recorded_result = recorded
        if recorded_request != request_json:
            return err("IDEMPOTENCY_KEY_REUSED")
        return json.loads(recorded_result)

    def _accept(
        self, job_id: str, command_id: str, command_type: str, new_state: str
    ) -> dict:
        event_id = str(uuid.uuid4())
        self.store.set_job_state(job_id, new_state)
        self.store.append_event(event_id, job_id, command_id, command_type, new_state)
        self.store.enqueue_notification(event_id)
        return ok(new_state, event_id)

    def pump(self) -> int:
        """Do any pending background work. Returns the number of items processed.

        Called periodically by the host process (a scheduler in production,
        the test harness in tests).
        """
        processed = 0
        while notification := self.store.next_notification():
            try:
                self.notifier.send(notification)
            except Exception:
                break
            self.store.mark_notification_delivered(notification["event_id"])
            processed += 1
        return processed
"""Durable state for relay, backed by sqlite.

Convention: this module is the only place that opens sqlite. Everything
durable goes through a connection from `connect()`, and multi-statement
writes go through `Store.tx()`.
"""
from __future__ import annotations

import contextlib
import sqlite3
import time
from typing import Iterator

from . import faults
from .model import Job

SCHEMA = """
CREATE TABLE IF NOT EXISTS jobs (
    job_id TEXT PRIMARY KEY,
    state  TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS events (
    seq        INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id   TEXT NOT NULL UNIQUE,
    job_id     TEXT NOT NULL,
    command_id TEXT NOT NULL,
    type       TEXT NOT NULL,
    state      TEXT NOT NULL,
    created_at REAL NOT NULL
);
CREATE TABLE IF NOT EXISTS commands (
    command_id   TEXT PRIMARY KEY,
    request_json TEXT NOT NULL,
    result_json  TEXT NOT NULL,
    created_at   REAL NOT NULL
);
CREATE TABLE IF NOT EXISTS outbox (
    event_id     TEXT PRIMARY KEY REFERENCES events(event_id),
    delivered_at REAL
);
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox (delivered_at, event_id);
"""


def connect(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path, isolation_level=None, check_same_thread=False)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=FULL")
    return faults.wrap(conn)


class Store:
    def __init__(self, path: str):
        self.path = path
        self.conn = connect(path)
        for stmt in SCHEMA.strip().split(";"):
            if stmt.strip():
                self.conn.execute(stmt)

    @contextlib.contextmanager
    def tx(self) -> Iterator[None]:
        """Run the block atomically. Nested use is not supported."""
        self.conn.execute("BEGIN IMMEDIATE")
        try:
            yield
        except BaseException:
            self.conn.execute("ROLLBACK")
            raise
        else:
            self.conn.execute("COMMIT")

    # -- jobs ---------------------------------------------------------------
    def get_job(self, job_id: str) -> Job | None:
        row = self.conn.execute("SELECT job_id, state FROM jobs WHERE job_id = ?", (job_id,)).fetchone()
        return Job(*row) if row else None

    def set_job_state(self, job_id: str, state: str) -> None:
        self.conn.execute(
            "INSERT INTO jobs (job_id, state) VALUES (?, ?) "
            "ON CONFLICT(job_id) DO UPDATE SET state = excluded.state",
            (job_id, state),
        )

    # -- commands -----------------------------------------------------------
    def get_command(self, command_id: str) -> tuple[str, str] | None:
        row = self.conn.execute(
            "SELECT request_json, result_json FROM commands WHERE command_id = ?",
            (command_id,),
        ).fetchone()
        return tuple(row) if row else None

    def record_command(self, command_id: str, request_json: str, result_json: str) -> None:
        self.conn.execute(
            "INSERT INTO commands (command_id, request_json, result_json, created_at) "
            "VALUES (?, ?, ?, ?)",
            (command_id, request_json, result_json, time.time()),
        )

    # -- events -------------------------------------------------------------
    def append_event(self, event_id: str, job_id: str, command_id: str, type_: str, state: str) -> None:
        self.conn.execute(
            "INSERT INTO events (event_id, job_id, command_id, type, state, created_at) VALUES (?, ?, ?, ?, ?, ?)",
            (event_id, job_id, command_id, type_, state, time.time()),
        )

    # -- outbox -------------------------------------------------------------
    def enqueue_notification(self, event_id: str) -> None:
        self.conn.execute("INSERT INTO outbox (event_id) VALUES (?)", (event_id,))

    def next_notification(self) -> dict | None:
        row = self.conn.execute(
            "SELECT e.event_id, e.job_id, e.type, e.state "
            "FROM outbox AS o JOIN events AS e ON e.event_id = o.event_id "
            "WHERE o.delivered_at IS NULL ORDER BY e.seq LIMIT 1"
        ).fetchone()
        if row is None:
            return None
        keys = ("event_id", "job_id", "type", "state")
        return dict(zip(keys, row))

    def mark_notification_delivered(self, event_id: str) -> None:
        self.conn.execute(
            "UPDATE outbox SET delivered_at = ? "
            "WHERE event_id = ? AND delivered_at IS NULL",
            (time.time(), event_id),
        )

    def read_events(self, job_id: str | None = None) -> list[dict]:
        if job_id is None:
            rows = self.conn.execute("SELECT seq, event_id, job_id, command_id, type, state FROM events ORDER BY seq").fetchall()
        else:
            rows = self.conn.execute(
                "SELECT seq, event_id, job_id, command_id, type, state FROM events WHERE job_id = ? ORDER BY seq",
                (job_id,),
            ).fetchall()
        keys = ("seq", "event_id", "job_id", "command_id", "type", "state")
        return [dict(zip(keys, r)) for r in rows]

    def close(self) -> None:
        self.conn.close()
# Relay reliability changes

- Added a durable command ledger keyed by `command_id`. It stores a canonical
  command envelope and the original result, so identical retries return that
  result without another transition, event, or notification. Reuse with a
  different type, job, or payload returns `IDEMPOTENCY_KEY_REUSED`. Rejections
  are recorded too, so their results cannot change on retry.
- Made command handling transactional with `BEGIN IMMEDIATE`. The job
  projection, event, outbox item, and command result now commit together. A
  second process rechecks the command ledger after acquiring the writer lock,
  preventing simultaneous retries from producing duplicate events.
- Made terminal states absorbing and added `cancel` transitions from both
  `queued` and `running`.
- Added a durable SQLite outbox. `handle` makes one best-effort delivery pass
  only after committing, and notifier failures do not escape from `handle`.
  `pump()` sends pending events in log order and marks each delivered only
  after the notifier returns successfully. A crash or ambiguous send can cause
  a safe duplicate, while an uncommitted event can never be selected.
- Added reliability coverage for command retries and key reuse, persisted
  rejections, terminal transitions, cancellation, sink outages, restart
  recovery, and ambiguous delivery failures.

Verification used `uv run --extra dev pytest`; all 17 tests passed. Additional
fault-injection checks killed the process after each transactional write and
immediately after commit: pre-commit deaths rolled everything back, while the
post-commit death recovered the job, event, command result, and pending outbox
item. A simultaneous two-caller probe also produced one event and one
notification with the same returned result for both callers.
